import{c as a,Q as i,j as n,m as l}from"./chunks/framework.DOi4mjdC.js";const t="/assets/Nd2Nz%E8%BD%AC%E6%8D%A2%E7%A4%BA%E6%84%8F%E5%9B%BE-%E6%96%B0-44.BOUYAk0B.png",s="/assets/Nd2Nz%E8%BD%AC%E6%8D%A2%E7%A4%BA%E6%84%8F%E5%9B%BE%EF%BC%882%EF%BC%89%E6%96%B0.Ce6_izUE.png",d=JSON.parse('{"title":"多核对齐切分","description":"","frontmatter":{},"headers":[{"level":1,"title":"多核对齐切分","slug":"多核对齐切分"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/多核对齐切分.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/多核对齐切分.md"}'),r={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/多核对齐切分.md"};function p(o,e,c,g,m,u){return i(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="多核对齐切分" tabindex="-1">多核对齐切分 <a class="header-anchor" href="#多核对齐切分" aria-label="Permalink to &quot;多核对齐切分&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>为了实现多核并行，提升计算效率，需要将矩阵数据进行切分，分配到不同的核上进行处理。主要的切分策略有切分K轴和不切分K轴两种。</p><p>不切分K轴、仅切分M、N轴的策略如下：</p><ul><li>对于A矩阵，沿着M轴进行切分，切分成多份的singleCoreM，单核上处理SingleCoreM * K大小的数据。</li><li>对于B矩阵，沿着N轴进行切分，切分成多份的singleCoreN，单核上处理K * SingleCoreN大小的数据。</li><li>对于C矩阵，SingleCoreM * K大小的A矩阵和K * SingleCoreN大小的B矩阵相乘得到SingleCoreM * SingleCoreN大小的C矩阵，即为单核上输出的C矩阵大小。</li></ul><p>比如，下图中共有8个核参与计算，将A矩阵沿着M轴划分为4块，将B矩阵沿着N轴切分为两块，单核上仅处理某一分块（比如图中绿色部分为core5上参与计算的数据）：SingleCoreM * K大小的A矩阵分块和SingleCoreN * K大小的B矩阵分块相乘得到SingleCoreM * SingleCoreN大小的C矩阵分块。</p><p><img src="'+t+'" alt=""></p><p>切分M、N、K轴的策略如下图所示：</p><ul><li>对于A矩阵，沿着M轴进行切分，切分成多份的singleCoreM，沿着K轴切分，切分成多份的singleCoreK，单核上处理singleCoreM * singleCoreK大小的数据。</li><li>对于B矩阵，沿着K轴进行切分，切分成多份的singleCoreK，沿着N轴进行切分，切分成多份的singleCoreN，单核上处理singleCoreK * singleCoreN大小的数据。</li><li>对于C矩阵，singleCoreM * singleCoreK大小的A矩阵与singleCoreK * singleCoreN大小的B矩阵相乘并累加得到singleCoreM * singleCoreN大小的C矩阵分块。</li></ul><p>比如下图中，C矩阵中的R矩阵块，是通过A1*B1+A2*B2+A3*B3累加得到的，其中，A1*B1、A2*B2、A3*B3可在多个核上并行计算。</p><p><img src="'+s+`" alt=""></p><p>上述的切分策略会在Tiling参数中体现，比如SingleCoreM、SingleCoreN、SingleCoreK，开发者在host侧通过调用API自动获取Tiling参数，与单核场景的不同的是，多核Tiling需要使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Matmul-Tiling%E7%B1%BB%E6%9E%84%E9%80%A0%E5%87%BD%E6%95%B0.md" target="_blank" rel="noreferrer">MultiCoreMatmulTiling</a>构造多核Tiling对象，并通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetDim.md" target="_blank" rel="noreferrer">SetDim</a>接口设置Matmul计算所用的核数。注意：这里设置的核数为Matmul计算可用的核数，仅在多核场景下设置，用于计算tiling参数；SetBlockDim为整个算子计算所用核数，是实际会加载的核数，是必须设置的。SetBlockDim的设置规则请参考<a href="./../../../../编程指南/附录/工程化算子开发/Host侧Tiling实现/基本流程.html#li1153191243910">numBlocks的说明</a>。SetDim的设置规则如下：</p><ul><li><p>纯Cube模式（只有矩阵计算）场景，本节内容以纯Cube模式举例。</p><p><a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetDim.md" target="_blank" rel="noreferrer">SetDim</a>设置当前AI处理器可用的核数，通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetTiling.md" target="_blank" rel="noreferrer">Tiling计算</a>得到执行Matmul计算实际使用的核数，实际使用的核数小于等于AI处理器可用的核数。SetBlockDim按照实际使用的核数由用户进行配置。</p></li><li><p>MIX模式（包含矩阵计算和矢量计算）的设置规则请参考<a href="./../算子实现.html#zh-cn_topic_0000001644252364_li4790115115920">MIX场景核数设置规则</a>。</p></li></ul><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>多核处理Matmul矩阵计算场景。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>该场景的关键代码示例如下。Matmul多核对齐场景的完整样例请参考：多核切M、N的样例：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/02_matrix/matmul_high_level_api" target="_blank" rel="noreferrer">Matmul多核Kernel直调样例</a>；多核切K的样例：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_splitk" target="_blank" rel="noreferrer">多核切K场景的算子样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 构造多核Tiling对象</span></span>
<span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();</span></span>
<span class="line"><span>matmul_tiling::MultiCoreMatmulTiling cubeTiling(*ascendcPlatform);</span></span>
<span class="line"><span>// 仅包含Cube计算的算子，设置可参与矩阵乘运算的核数为当前AI处理器上的Cube核数</span></span>
<span class="line"><span>cubeTiling.SetDim(ascendcPlatform.GetCoreNumAic());</span></span>
<span class="line"><span>cubeTiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);</span></span>
<span class="line"><span>cubeTiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);</span></span>
<span class="line"><span>cubeTiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);</span></span>
<span class="line"><span>cubeTiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);</span></span>
<span class="line"><span>cubeTiling.SetOrgShape(M, N, K);</span></span>
<span class="line"><span>cubeTiling.SetShape(M, N, K);</span></span>
<span class="line"><span>cubeTiling.EnableBias(isBias);</span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;  </span></span>
<span class="line"><span>// 获取Tiling参数 </span></span>
<span class="line"><span>int ret = cubeTiling.GetTiling(tilingData);    // if ret = -1, gen tiling failed</span></span></code></pre></div>`,20)])])}const C=a(r,[["render",p]]);export{d as __pageData,C as default};
